package com.nhlocal.singlesorter.app;
public final class ReservedScopePolicyTest {
 private ReservedScopePolicyTest(){}
 public static void main(String[] args)throws Exception{int count=0;int[] kind={-1,0,1,2};for(boolean released:new boolean[]{false,true})for(boolean absent:new boolean[]{false,true})for(int value:kind){int expected=value!=1&&value!=2&&released&&absent?0:value==2?2:1;if(ReservedScopePolicy.select(value,released,absent)!=expected)throw new AssertionError();count++;}for(int value:kind){try{boolean reserved=ReservedScopePolicy.stillReserved(value);if(reserved!=(value==2)||value==-1||value==1)throw new AssertionError();}catch(java.io.IOException expected){if(value==0||value==2||!"RESERVED_PARENT_UNAVAILABLE".equals(expected.getMessage()))throw new AssertionError();}count++;}for(String[] row:new String[][]{{"primary:Music","primary:Music/a.mp3","y"},{"primary:music","primary:Music/a.mp3","y"},{"primary:","primary:Music","y"},{"primary:Music","primary:Music2/a.mp3","n"},{"primary:Music","primary:Music","n"},{"primary:Music/a","primary:Music","n"},{"primary:Music","home:Music/a.mp3","n"}}){if(ReservedScopePolicy.mayContain(row[0],row[1])!=row[2].equals("y"))throw new AssertionError(row[1]);count++;}System.out.println(count+" retained backup, lost-return and repeated-job namespace checks passed");}
}
